package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Soft-closes an open period, by the roles the sheet allows to close (see {@link PeriodCloser#softClose}). */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods,
            Settings settings, PeriodCloser closer, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!settings.allows(sheetId, request.user(), "close")) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.closed() || period.softClosed()) {
            throw new InvalidPeriodException("The period " + name + " is already closed or soft-closed");
        }
        closer.softClose(sheetId, period, request.user());
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;

/** A rollover that passed validation: the old fiscal year's name (FY<yyyy>), its periods by from-date (at least
 *  one), and the new fiscal year's twelve months to generate. */
public record ValidRollover(String fiscalYear, List<PeriodResponse> periods, ValidGenerate next, String user) {
}
package net.officefloor.hq.app.period;

import java.sql.Date;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.opening.Openings;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Undoes the sheet's last rollover: by the steward who made it, on the sheet's today it was made, and only while no
 * claim (of any status) belongs to a period it generated. The periods it generated are removed and the openings it
 * set taken back, then ROLLOVER_UNDONE with the old fiscal year.
 */
public class UndoRollover {
    public void undo(@PathVariable("sheetId") String sheetId, @RequestBody RolloverUndoRequest request,
            Rollovers rollovers, Periods periods, Openings openings, Settings settings, Sheets sheets,
            JdbcTemplate jdbc, Audit audit, ObjectResponse<GenerateResponse> response)
            throws InvalidPeriodException, ViewerRefusedException {
        String user = request.user();
        settings.refuseViewer(sheetId, user);
        if (!Settings.STEWARD.equals(settings.role(sheetId, user))) {
            throw new InvalidPeriodException("Only a steward may undo a rollover");
        }
        Rollovers.Rollover last = rollovers.last(sheetId);
        if (last == null || last.undone()) {
            throw new InvalidPeriodException("There is no rollover to undo");
        }
        if (!last.user().equals(user)) {
            throw new InvalidPeriodException("Only the steward who rolled the year over may undo it");
        }
        if (!last.madeOn().equals(sheets.today(sheetId))) {
            throw new InvalidPeriodException("A rollover can be undone only on the day it was made");
        }
        for (String name : last.periods()) {
            PeriodResponse period = periods.lock(sheetId, name);
            if (period == null) {
                continue;
            }
            Integer claimed = jdbc.queryForObject(
                    "SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND claim_date >= ? AND claim_date <= ?", Integer.class,
                    sheetId, Date.valueOf(period.from()), Date.valueOf(period.to()));
            if (claimed != null && claimed > 0) {
                throw new InvalidPeriodException("A claim belongs to period " + name + " the rollover generated");
            }
        }
        last.periods().forEach(name -> periods.remove(sheetId, name));
        openings.removeByRollover(sheetId, last.id());
        rollovers.undone(last.id());
        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=" + last.fiscalYear());
        response.send(new GenerateResponse(last.periods().size(), periods.list(sheetId)));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A rollover is by a steward only, of a year (YYYY) whose fiscal year has at least one period on the sheet (a
 *  period belongs to the fiscal year its from-date falls in). */
public class ValidateRollover {

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RolloverRequest request,
            Out<ValidRollover> body, Periods periods, Settings settings)
            throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPeriodException("Only a steward may roll the year over");
        }
        String year = request.year() == null ? "" : request.year().trim();
        if (!year.matches("\\d{4}")) {
            throw new InvalidPeriodException("The fiscal year must be a year (YYYY)");
        }
        LocalDate from = LocalDate.of(Integer.parseInt(year), settings.fiscalStartMonth(sheetId), 1);
        LocalDate next = from.plusMonths(12);
        List<PeriodResponse> inYear = periods.list(sheetId).stream()
                .filter(p -> !LocalDate.parse(p.from()).isBefore(from) && LocalDate.parse(p.from()).isBefore(next))
                .toList();
        if (inYear.isEmpty()) {
            throw new InvalidPeriodException("No period of FY" + year + " is on the sheet");
        }
        body.set(new ValidRollover("FY" + year, inYear,
