  test("rollover soft closes scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "clerk-limit", "3.00");
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "terms-A", "20");
    await ui.setSetting(pg_uma, "cap", "5.00");
    await ui.setSetting(pg_uma, "proof-threshold", "3.00");
    await ui.setSetting(pg_uma, "perm-settle", "steward");
    expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "note-threshold", "2.50");
    expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "10.35", "note": "tpl"})).toBe(true);
    await ui.setSetting(pg_uma, "fiscal-start-month", "4");
    await ui.setSetting(pg_uma, "score-mid", "0");
    await ui.setSetting(pg_uma, "score-high", "1");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "20"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": "ben@x"}));
    expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
    expect(await ui.addCrewMember(pg_uma, "C1", "Cam")).toBe(true);
    expect(await ui.addCrewMember(pg_uma, "C1", "Ben")).toBe(true);
    expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-05", "to": "2026-03-09"})).toBe(true);
    await ui.setToday(pg_uma, "2026-03-30");
    const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "3.33"}, p_cam));
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.merge(pg_wes, p_cam, "Ben")).toBe(true);
    const c_ben_0 = await ui.claimAt(pg_wes, p_ben, 0);
    expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.watch(pg_wes, p_ada, true)).toBe(true);
    expect(await ui.generateQuarters(pg_wes, "2026")).toBe(4);
    await ui.refresh(pg_wes);
    expect(await ui.importPeople(pg_wes, "Ada,B")).toMatchObject({"added": 0, "updated": 1});
    expect(await ui.importRates(pg_wes, "C,33.33\nB,10.00,2026-03-05")).toBe(2);
    expect(await ui.claimAction(pg_wes, c_ben_0, "void", "dup")).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ben, {"terms": "20"})).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ada, {"terms": "3"})).toBe(true);
    expect(await ui.periodAction(pg_wes, "2026-Q3", "soft-close")).toBe(true);
    await ui.setPreview(pg_wes, "2026-05-01");
    await ui.refresh(pg_wes);
    await ui.clearPreview(pg_wes);
    await ui.refresh(pg_wes);
    expect(await ui.movePerson(pg_wes, p_ben, "down")).toBe(false);
    const c_ada_0 = ui.must(await ui.claimFromTemplate(pg_wes, p_ada, "T1"));
    expect(await ui.importRates(pg_wes, "B,20.00\nA,12.50,2026-03-05")).toBe(2);
    expect(await ui.inlineGrade(pg_wes, p_ben, "A")).toBe(true);
    expect(await ui.hold(pg_wes, p_ada, {"from": "2026-03-05", "to": "2026-03-15"})).toBe(true);
    await ui.setAsOf(pg_wes, "2026-03-28");
    await ui.refresh(pg_wes);
